head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    gridView1.setHeaderDisabled("column3", true);
};
scwin.trigger2_onclick = function(e) {
    gridView1.setHeaderDisabled("column3", false);
};
scwin.headerClick = function(headerId) {
    localStorage.setItem("headerclick", "true");
    //alert(localStorage.getItem('header'));		
};
scwin.checkVal1 = function() {
    return localStorage.getItem('headerclick') != 'true';
}
scwin.checkVal2 = function() {
    return localStorage.getItem('headerclick') == 'true';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. IE에서 샘플파일 실행 후 input1의 inputbox에 한글을 입력한다.
    //1. After executing the sample file in IE, input Hangul in the input box of input1.
    //Verify step 1. Hangul is entered normally.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3').click()");
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('headerclick')");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
